# Directional drift experiment on YFCC DINO embeddings.
#
# The shift direction is based on the real temporal drift of the dataset:
# i computed the mean embedding per year and use the vector from the 2007 mean to the 
# 2013 mean as the drift direction. 
# Query sets were generated by taking a random sample of index vectors and displacing them by increasing multiples of that direction. 
# This is the same structure as the synthetic continuous drift experiment, but the direction is based on the actual structure and drift of the data.
#
# Index: random sample of n_index vectors from all years.
# Queries: n_index_sample vectors shifted by sigma * drift_direction,
#          for sigma in shift_sigmas.
#
# Saves summary.csv, per_query.csv, lb_traces.csv, params.csv

import os
import argparse
import numpy as np
import pandas as pd

import hnswlib

rng = np.random.default_rng(42)

parser = argparse.ArgumentParser()
parser.add_argument("--embeddings_path", required=True)
parser.add_argument("--metadata_path",   required=True)
parser.add_argument("--n_index",         type=int,   default=None,
                    help="cap on index vectors (default: use all available)")
parser.add_argument("--n_queries",       type=int,   default=1_000)
parser.add_argument("--shift_sigmas",    type=float, nargs="+",
                    default=[0, 1, 2, 3, 4, 6, 8, 10, 12, 16])
parser.add_argument("--ef_sweep",        type=int,   nargs="+",
                    default=[10, 20, 50, 100, 200, 500])
parser.add_argument("--M",               type=int,   default=16)
parser.add_argument("--ef_construction", type=int,   default=200)
parser.add_argument("--k",               type=int,   default=10)
parser.add_argument("--out_dir",         default="results_yfcc_directional_drift")
args = parser.parse_args()

dim = 384
os.makedirs(args.out_dir, exist_ok=True)


# --- loading -----------------------------------------------------------------

def load_embeddings():
    print(f"loading embeddings...")
    emb  = np.load(args.embeddings_path, mmap_mode='r')
    meta = pd.read_csv(args.metadata_path)
    assert len(emb) == len(meta), "embedding/metadata length mismatch"
    print(f"  {len(emb):,} embeddings, dim={emb.shape[1]}")
    print(f"  year distribution:\n{meta.groupby('year').size().to_string()}")
    return emb, meta


# --- drift direction ---------------------------------------------------------

def compute_drift_direction(emb, meta):
    # use the vector from the 2007 mean to the 2013 mean as the drift direction
    # is grounded on the actual temporal drift of the dataset
    mean_2007 = np.array(emb[(meta['year'] == 2007).values], dtype=np.float32).mean(axis=0)
    mean_2013 = np.array(emb[(meta['year'] == 2013).values], dtype=np.float32).mean(axis=0)

    direction = mean_2013 - mean_2007
    magnitude = np.linalg.norm(direction)
    direction /= magnitude

    print(f"\ndrift direction:")
    print(f"  2007 mean norm: {np.linalg.norm(mean_2007):.3f}")
    print(f"  2013 mean norm: {np.linalg.norm(mean_2013):.3f}")
    print(f"  displacement magnitude: {magnitude:.3f}")

    return direction.astype(np.float32), magnitude


# --- index + query sets ------------------------------------------------------

def build_splits(emb, meta, direction, displacement_magnitude):
    # index: use all available vectors (up to n_index)
    n_total = len(emb)
    if args.n_index and n_total > args.n_index:
        chosen = rng.choice(n_total, args.n_index, replace=False)
        chosen.sort()
        index_vecs = np.array(emb[chosen], dtype=np.float32)
    else:
        index_vecs = np.array(emb, dtype=np.float32)
    print(f"\nindex: {len(index_vecs):,} vectors (all years)")
 
    # query base: independent random sample from all vectors
    q_idx = rng.choice(n_total, args.n_queries, replace=False)
    q_idx.sort()
    query_base = np.array(emb[q_idx], dtype=np.float32)
    print(f"queries: {len(query_base):,} base vectors (independent sample)")
 
    # shift the query base along the drift direction
    # sigma is in units of the 2007->2013 displacement magnitude so that
    # sigma=1 corresponds to one full year-span of real temporal drift
    query_sets = {}
    for sigma in args.shift_sigmas:
        shift = direction * sigma * displacement_magnitude
        query_sets[sigma] = query_base + shift
        print(f"  sigma={sigma:>5}  |shift| = {np.linalg.norm(shift):.2f}")
 
    return index_vecs, query_sets


# --- ground truth ------------------------------------------------------------

def compute_gt(index_vecs, queries):
    import faiss
    index = faiss.IndexFlatL2(dim)
    index.add(np.ascontiguousarray(index_vecs, dtype=np.float32))
    _, neighbours = index.search(
        np.ascontiguousarray(queries, dtype=np.float32), args.k
    )
    return neighbours.astype(np.int32)


# --- hnsw index + querying ---------------------------------------------------

def build_index(data):
    idx = hnswlib.Index(space="l2", dim=dim)
    idx.init_index(
        max_elements=len(data),
        ef_construction=args.ef_construction,
        M=args.M
    )
    idx.add_items(data, np.arange(len(data), dtype=np.int32))
    return idx


def recall(predicted, ground_truth):
    hits = sum(len(set(p) & set(g)) for p, g in zip(predicted, ground_truth))
    return hits / (len(ground_truth) * ground_truth.shape[1])


def query_index(idx, queries, gt):
    results = []
    for i, q in enumerate(queries):
        pred, _ = idx.knn_query(q.reshape(1, -1), k=args.k)
        s = hnswlib.get_last_query_stats()
        results.append({
            "recall":               recall(pred, gt[i:i+1]),
            "ep_dist":              float(s["entry_point_distance"]),
            "bl_entry_dist":        float(s["base_layer_entry_distance"]),
            "ul_dist_comps":        int(s["upper_layer_distance_computations"]),
            "layer_visits":         list(s["layer_visit_counts"]),
            "base_visited":         int(s["base_layer_visited_count"]),
            "base_dist_comps":      int(s["base_layer_distance_computations"]),
            "candidates_remaining": int(s["candidates_remaining_at_termination"]),
            "lb_trace":             list(s["lowerbound_trace"]),
        })
    return results


# --- saving ------------------------------------------------------------------

def save_params(direction, displacement_magnitude, path):
    rows = [
        {"param": "dataset",               "value": "YFCC-DINO"},
        {"param": "dim",                   "value": dim},
        {"param": "n_index",               "value": args.n_index},
        {"param": "n_queries",             "value": args.n_queries},
        {"param": "shift_sigmas",          "value": str(args.shift_sigmas)},
        {"param": "displacement_magnitude","value": round(float(displacement_magnitude), 4)},
        {"param": "ef_sweep",              "value": str(args.ef_sweep)},
        {"param": "M",                     "value": args.M},
        {"param": "ef_construction",       "value": args.ef_construction},
        {"param": "k",                     "value": args.k},
        {"param": "drift_direction",       "value": "mean_2007_to_mean_2013"},
        {"param": "rng_seed",              "value": 42},
    ]
    pd.DataFrame(rows).to_csv(path, index=False)
    print(f"  saved {path}")


def save_summary(all_results, path):
    rows = []
    for (sigma, ef), results in sorted(all_results.items()):
        def avg(field):
            return float(np.nanmean([r[field] for r in results]))
        l1 = [r["layer_visits"][1] for r in results if len(r["layer_visits"]) > 1]
        rows.append({
            "shift_sigma":                  sigma,
            "ef_search":                    ef,
            "mean_recall":                  avg("recall"),
            "mean_ep_distance":             avg("ep_dist"),
            "mean_bl_entry_distance":       avg("bl_entry_dist"),
            "mean_ul_dist_comps":           avg("ul_dist_comps"),
            "mean_layer1_visits":           float(np.mean(l1)) if l1 else float("nan"),
            "mean_base_visited":            avg("base_visited"),
            "mean_base_dist_comps":         avg("base_dist_comps"),
            "mean_candidates_remaining":    avg("candidates_remaining"),
            "n_queries":                    len(results),
        })

    df = pd.DataFrame(rows).round(4)
    df.to_csv(path, index=False)
    print(f"  saved {path}")

    pivot = df.pivot(index="shift_sigma", columns="ef_search",
                     values="mean_recall").round(3)
    print("\nRecall@k (rows=shift sigma, cols=ef):")
    print(pivot.to_string())


def save_per_query(all_results, path):
    rows = []
    for (sigma, ef), results in sorted(all_results.items()):
        for i, r in enumerate(results):
            row = {
                "shift_sigma":          sigma,
                "ef_search":            ef,
                "query_id":             i,
                "recall":               r["recall"],
                "ep_dist":              r["ep_dist"],
                "bl_entry_dist":        r["bl_entry_dist"],
                "ul_dist_comps":        r["ul_dist_comps"],
                "base_visited":         r["base_visited"],
                "base_dist_comps":      r["base_dist_comps"],
                "candidates_remaining": r["candidates_remaining"],
                "lb_trace_final":       r["lb_trace"][-1] if r["lb_trace"] else float("nan"),
                "lb_trace_len":         len(r["lb_trace"]),
            }
            for layer, visits in enumerate(r["layer_visits"]):
                row[f"layer{layer}_visits"] = visits
            rows.append(row)
    pd.DataFrame(rows).round(6).to_csv(path, index=False)
    print(f"  saved {path}")


def save_lb_traces(all_results, path):
    rows = []
    for (sigma, ef), results in sorted(all_results.items()):
        traces = [r["lb_trace"] for r in results if r["lb_trace"]]
        if not traces:
            continue
        min_len    = min(len(t) for t in traces)
        mean_trace = np.mean([t[:min_len] for t in traces], axis=0)
        for iteration, value in enumerate(mean_trace):
            rows.append({
                "shift_sigma":     sigma,
                "ef_search":       ef,
                "iteration":       iteration,
                "mean_lowerbound": round(float(value), 6),
            })
    pd.DataFrame(rows).to_csv(path, index=False)
    print(f"  saved {path}")


# --- main --------------------------------------------------------------------

def main():
    print("YFCC directional drift experiment")
    #fix because if n_index not specified, (is None) f String fails
    n_index_label = f"{args.n_index:,}" if args.n_index else "all"
    print(f"n_index={n_index_label}  n_queries={args.n_queries}  k={args.k}")
    print(f"shift_sigmas={args.shift_sigmas}")
    print(f"ef_sweep={args.ef_sweep}\n")

    emb, meta = load_embeddings()

    direction, displacement_magnitude = compute_drift_direction(emb, meta)

    index_vecs, query_sets = build_splits(emb, meta, direction, displacement_magnitude)
    del emb

    print(f"\nbuilding index on {len(index_vecs):,} vectors...")
    idx = build_index(index_vecs)
    print(f"  done  (M={args.M}, ef_construction={args.ef_construction})")

    print(f"\ncomputing ground truth")
    ground_truths = {}
    for sigma, queries in sorted(query_sets.items()):
        print(f"  sigma={sigma}")
        ground_truths[sigma] = compute_gt(index_vecs, queries)
    print("  done")

    print(f"\nquerying: {len(query_sets)} shift levels x {len(args.ef_sweep)} ef values")
    all_results = {}

    for ef in args.ef_sweep:
        idx.set_ef(ef)
        print(f"\nef={ef}")
        for sigma, queries in sorted(query_sets.items()):
            results = query_index(idx, queries, ground_truths[sigma])
            all_results[(sigma, ef)] = results
            mean_r  = np.mean([r["recall"] for r in results])
            mean_ep = np.nanmean([r["ep_dist"] for r in results])
            mean_bl = np.nanmean([r["bl_entry_dist"] for r in results])
            print(f"  sigma={sigma:>5}  recall={mean_r:.4f}  "
                  f"ep={mean_ep:.1f}  bl_entry={mean_bl:.1f}")

    print("\nsaving results...")
    save_params(direction, displacement_magnitude,
                os.path.join(args.out_dir, "params.csv"))
    save_summary(all_results,   os.path.join(args.out_dir, "summary.csv"))
    save_per_query(all_results, os.path.join(args.out_dir, "per_query.csv"))
    save_lb_traces(all_results, os.path.join(args.out_dir, "lb_traces.csv"))
    print(f"\ndone — results in {os.path.abspath(args.out_dir)}")


if __name__ == "__main__":
    main()